using UnscRelay.Core;
internal static class RecoveryIdentityBindingChecks
{
 sealed class NoNetwork:HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellation)=>throw new Exception("Binding check must not contact another service");}
 public static int Run(){var root=Directory.CreateTempSubdirectory("relay-recovery-binding-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS recovery identity binding: "+label);}try{using var client=new CloudAccountClient(root.FullName,new NoNetwork());client.State.Owner=new string('A',64);client.State.Subject="61616161-6161-4161-8161-616161616161";client.State.AccessToken="old-session-must-remain";client.Save();var bytes=File.ReadAllBytes(Path.Combine(root.FullName,"account-sync.dpapi"));var identity=new OnlineIdentity(client.State.Owner,client.State.Subject,"Fixture","fixture@example.invalid");client.RequireBoundIdentity(identity);Check(true,"fresh verification accepts the exact previously bound owner and subject");foreach(var candidate in new[]{identity with{Owner=new string('B',64)},identity with{Subject="62626262-6262-4262-8262-626262626262"},identity with{Owner=new string('B',64),Subject="62626262-6262-4262-8262-626262626262"}}){try{client.RequireBoundIdentity(candidate);throw new Exception("Different identity accepted");}catch(OnlineAccessException){Check(client.State.AccessToken=="old-session-must-remain"&&File.ReadAllBytes(Path.Combine(root.FullName,"account-sync.dpapi")).SequenceEqual(bytes),"another owner or subject is rejected before replacing session or account metadata");}}Console.WriteLine("Recovery identity binding checks: "+count);return 0;}finally{root.Delete(true);}}
}
